import{_ as e,c as o,o as t,a5 as a}from"./chunks/framework.Djspl_t8.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"定语与状语.md","filePath":"定语与状语.md"}'),s={name:"定语与状语.md"},n=a('<h2 id="定语是广义的形容词" tabindex="-1">定语是广义的形容词 <a class="header-anchor" href="#定语是广义的形容词" aria-label="Permalink to &quot;定语是广义的形容词&quot;">​</a></h2><p>形容词用来修饰名词或代词，其一般可以被翻译为“......的”：</p><blockquote><p>The <em><strong>cute</strong></em> boy speaks English.<br> （那个可爱的男孩会说英语。）</p></blockquote><p>形容词<em>cute</em>修饰名词boy，表达“可爱的男孩”之意。</p><p>但形容词是词类，我们很难用它来表达更加丰富的语义。</p><p>比如我们要表达“穿红衣服的男孩”或是“刚刚和我一起玩的男孩”，形容词就无能为力了。</p><p>因此在一些情景中，我们使用另外一些表达能力更为丰富的结构来充当形容词，比如介词短语和定语从句等：</p><blockquote><p>The boy <em><strong>in red</strong></em> speaks English. （穿红衣服的男孩会说英语。）</p></blockquote><blockquote><p>The boy <em><strong>whom I played with</strong></em> speaks English.<br> （刚刚和我一起玩的男孩会说英语。)</p></blockquote><p>我们将形容词“<em>cute</em>”、介词短语“<em>in red</em>”、定语从句“<em>whom I played with</em>”这类可以充当形容词使用的结构称为定语，此类结构作定语时均可以被翻译为“......的”。</p><p>所以，我们称<strong>定语是广义的形容词</strong>。</p><h2 id="状语是广义的副词" tabindex="-1">状语是广义的副词 <a class="header-anchor" href="#状语是广义的副词" aria-label="Permalink to &quot;状语是广义的副词&quot;">​</a></h2><p>副词和状语的关系与形容词和定语的关系类似。</p><p>副词用来修饰除名词和代词外的其它结构，比如动词、形容词、副词、短语、句子等，例如：</p><blockquote><p>James answered <em><strong>quickly</strong></em>. （James迅速回答。）</p></blockquote><p>副词<em>quickly</em>修饰动词answer，表达“迅速回答”之意。</p><p>由于词类表达能力的局限性，有时需要其它结构来充当副词以表达更丰富的语义。</p><p>比如我们要表达“James用英语回答”，却发现并没有词意为“用英语”的副词。</p><p>此时就可以用介词短语“<em>in English</em>”充当副词，来修饰动词answer：</p><blockquote><p>James answered <em><strong>in English</strong>.</em> （James用英语回答。）</p></blockquote><p>再比如，我们要表达“当我还没有想法的时候，James回答了。”，则可以用状语从句“<em>when I had no idea</em>”充当副词，来修饰句子“James answered”：</p><blockquote><p><em><strong>When I had no idea</strong></em>，James answered. （当我还没有想法的时候，James回答了。）</p></blockquote><p>我们称副词“<em>quickly</em>”、介词短语“<em>in English</em>”、状语从句“w<em>hen I had no idea</em>”这类可以充当副词使用的结构为状语。</p><p>所以，我们称<strong>状语是广义的副词</strong>。</p><p>希望上述内容能够对大家有所帮助。</p><p>来源知乎<a href="https://zhuanlan.zhihu.com/p/27459344" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/27459344</a></p>',26),p=[n];function r(m,l,c,h,i,d){return t(),o("div",null,p)}const g=e(s,[["render",r]]);export{u as __pageData,g as default};
